<?php require_once __DIR__.'/includes/bootstrap.php';require_login('subscribe to alerts');if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: services-programs.php');exit;}check_csrf();$email=trim($_POST['email']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)){header('Location: services-programs.php?error=email');exit;}$pdo->exec('CREATE TABLE IF NOT EXISTS subscribers(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,email VARCHAR(255) NOT NULL,subscribed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)');$s=$pdo->prepare('INSERT INTO subscribers(user_id,email) VALUES(?,?) ON DUPLICATE KEY UPDATE email=VALUES(email)');$s->execute([(int)$_SESSION['user']['id'],$email]);header('Location: services-programs.php?subscribed=1');exit;
